declare(strict_types=1);

namespace App\Tests\Api;

use App\Platform\Settings\ConfigRevision;
use App\Tests\Support\Fixtures;
use App\Tests\Support\TestContainer;

/**
 * /api/v1/blog over HTTP: CRUD, ETag/If-Match locking, validation shape, pagination, scopes, permissions, lifecycle.
 */
final class ApiBlogTest extends ApiTestCase
{
    private static bool $revisionBumped = false;
    private array $admin;
    private string $token;

    protected function setUp(): void
    {
        parent::setUp();
        if (!self::$revisionBumped) {
            // a freshly migrated module flag must be visible to the running PHP-FPM workers (flag cache)
            TestContainer::service(ConfigRevision::class)->bump();
            self::$revisionBumped = true;
        }
        $this->admin = Fixtures::user(['business_admin']);
        $this->token = $this->token($this->admin)['access_token'];
    }

    public function testCrudWithOptimisticLocking(): void
    {
        $r = $this->api('POST', '/api/v1/blog', $this->token, $this->input() + ['unknown_field' => 'ignored']);
        self::assertSame(201, $r->getStatusCode(), $this->http->body());
        $e = $this->json($r)['data'];
        self::assertSame('/api/v1/blog/' . $e['id'], $r->getHeaderLine('Location'));
        self::assertSame('"1"', $r->getHeaderLine('ETag'));
        self::assertArrayNotHasKey('unknown_field', $e);

        $r = $this->api('GET', '/api/v1/blog/' . $e['id'], $this->token);
        self::assertSame(200, $r->getStatusCode());
        self::assertSame($e['id'], $this->json($r)['data']['id']);

        $value = 'Updated title ' . bin2hex(random_bytes(4));
        $this->assertError($this->api('PATCH', '/api/v1/blog/' . $e['id'], $this->token, ['title' => $value]), 428, 'precondition_required');
        $r = $this->api('PATCH', '/api/v1/blog/' . $e['id'], $this->token, ['title' => $value], ['If-Match' => '"1"']);
        self::assertSame(200, $r->getStatusCode(), $this->http->body());
        self::assertSame('"2"', $r->getHeaderLine('ETag'));
        $this->assertError($this->api('PATCH', '/api/v1/blog/' . $e['id'], $this->token, ['title' => $value], ['If-Match' => '"1"']), 409, 'stale_version');

        $r = $this->api('DELETE', '/api/v1/blog/' . $e['id'], $this->token, null, ['If-Match' => '"2"']);
        self::assertSame(204, $r->getStatusCode(), $this->http->body());
        $this->assertError($this->api('GET', '/api/v1/blog/' . $e['id'], $this->token), 404, 'not_found');
    }

    public function testValidationErrorShape(): void
    {
        $e = $this->assertError($this->api('POST', '/api/v1/blog', $this->token, [
            'title' => str_repeat('x', 256),
            'description' => str_repeat('x', 501),
            'due_on' => '2026-13-45',
        ]), 422, 'validation_failed');
        foreach (['title', 'description', 'due_on'] as $field) {
            self::assertIsList($e['details'][$field] ?? null, $field);
        }
    }

    public function testListPaginationScopesAndAuth(): void
    {
        $this->api('POST', '/api/v1/blog', $this->token, $this->input());
        $this->api('POST', '/api/v1/blog', $this->token, $this->input());
        $r = $this->api('GET', '/api/v1/blog?per_page=1&sort=-created_at', $this->token);
        self::assertSame(200, $r->getStatusCode(), $this->http->body());
        $d = $this->json($r);
        self::assertCount(1, $d['data']);
        self::assertGreaterThanOrEqual(2, (int) $r->getHeaderLine('X-Total-Count'));
        self::assertNotNull($d['links']['next']);

        $this->assertError($this->api('GET', '/api/v1/blog', null), 401, 'unauthorized');
        // a token without the module scope is refused even though the user holds the permission
        $profileOnly = $this->token($this->admin, 'profile')['access_token'];
        $this->assertError($this->api('GET', '/api/v1/blog', $profileOnly), 403, 'insufficient_scope');
        // a user without blog.create
        $user = Fixtures::user(['user']);
        $this->assertError($this->api('POST', '/api/v1/blog', $this->token($user)['access_token'], $this->input()), 403, 'forbidden');
    }

    public function testStatusTransitions(): void
    {
        $e = $this->json($this->api('POST', '/api/v1/blog', $this->token, $this->input()))['data'];
        self::assertSame('draft', $e['status']);
        self::assertContains('active', $e['allowed_transitions']);
        $r = $this->api('POST', '/api/v1/blog/' . $e['id'] . '/status', $this->token, ['status' => 'active', 'comment' => 'API']);
        self::assertSame(200, $r->getStatusCode(), $this->http->body());
        self::assertSame('active', $this->json($r)['data']['status']);
        $this->assertError($this->api('POST', '/api/v1/blog/' . $e['id'] . '/status', $this->token, ['status' => 'draft']), 409, 'invalid_transition');
        $this->assertError($this->api('POST', '/api/v1/blog/' . $e['id'] . '/status', $this->token, ['status' => 'bogus']), 422, 'validation_failed');
    }

    private function input(): array
    {
        return [
            'title' => 'Sample title ' . bin2hex(random_bytes(4)),
            'description' => 'Sample description ' . bin2hex(random_bytes(4)),
            'due_on' => '2026-12-31',
        ];
    }
}
